import { afterEach, beforeEach, describe, expect, test } from "bun:test";
import { execFileSync } from "node:child_process";
import { existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { tmpdir } from "node:os";
import {
  WORKTREE_BRANCH,
  WORKTREE_DIR,
  detectInitScenario,
  initFreshWorktree,
  initJoinWorktree,
  initWorktree,
  isWorktreeInitialized,
  pullWorktree,
  pushWorktree,
} from "../../src/core/worktree";
import { AgentrackError } from "../../src/core/errors";

// ─── Test helpers ──────────────────────────────────────────────────────

/**
 * Create a temporary directory for test isolation.
 */
function createTestDir(prefix = "worktree-test"): string {
  return mkdtempSync(join(tmpdir(), `${prefix}-`));
}

function mkdtempSync(prefix: string): string {
  const dir = join(prefix, `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`);
  mkdirSync(dir, { recursive: true });
  return dir;
}

/**
 * Run a git command in the given directory.
 */
function git(cwd: string, args: string[]): string {
  return execFileSync("git", args, { cwd, encoding: "utf-8", stdio: ["pipe", "pipe", "pipe"] });
}

/**
 * Create a minimal git repo with user config.
 */
function initGitRepo(dir: string): void {
  git(dir, ["init"]);
  git(dir, ["config", "user.name", "Test User"]);
  git(dir, ["config", "user.email", "test@example.com"]);
}

/**
 * Create an initial commit on the main branch so it has history.
 */
function makeInitialCommit(dir: string): void {
  writeFileSync(join(dir, "README.md"), "# Test\n", "utf-8");
  git(dir, ["add", "README.md"]);
  git(dir, ["commit", "-m", "initial commit"]);
}

/**
 * Set up a "remote" bare repo and a working clone.
 * Returns { remote, work } — both are directory paths.
 */
function setupRemoteAndClone(): { remote: string; work: string } {
  const base = createTestDir();
  const remote = join(base, "remote.git");
  const work = join(base, "work");

  // Create bare remote
  git(base, ["init", "--bare", remote]);
  // Clone it
  git(base, ["clone", remote, work]);
  git(work, ["config", "user.name", "Test User"]);
  git(work, ["config", "user.email", "test@example.com"]);

  // Make initial commit so HEAD is not unborn
  makeInitialCommit(work);
  git(work, ["push", "-u", "origin", "HEAD"]);

  return { remote, work };
}

/**
 * Clean up a directory tree.
 */
function cleanup(dir: string): void {
  // Worktrees can be tricky to remove — prune first
  try {
    git(dir, ["worktree", "prune"]);
  } catch {
    // ignore
  }
  rmSync(dir, { recursive: true, force: true });
}

// ─── Constants ─────────────────────────────────────────────────────────

describe("worktree constants", () => {
  test("WORKTREE_BRANCH is '_agentrack'", () => {
    expect(WORKTREE_BRANCH).toBe("_agentrack");
  });

  test("WORKTREE_DIR is '.agentrack'", () => {
    expect(WORKTREE_DIR).toBe(".agentrack");
  });
});

// ─── detectInitScenario ────────────────────────────────────────────────

describe("detectInitScenario", () => {
  let work: string;
  let base: string;

  beforeEach(() => {
    base = createTestDir();
    work = join(base, "work");
    initGitRepo(work);
    makeInitialCommit(work);
  });

  afterEach(() => {
    cleanup(base);
  });

  test("returns 'fresh' when no remote branch exists", () => {
    // Add a dummy remote so ls-remote doesn't fail
    const remote = join(base, "remote.git");
    git(base, ["init", "--bare", remote]);
    git(work, ["remote", "add", "origin", remote]);
    git(work, ["push", "-u", "origin", "HEAD"]);

    const scenario = detectInitScenario(work);
    expect(scenario).toBe("fresh");
  });

  test("returns 'join' when remote _agentrack branch exists", () => {
    const remote = join(base, "remote.git");
    git(base, ["init", "--bare", remote]);
    git(work, ["remote", "add", "origin", remote]);
    git(work, ["push", "-u", "origin", "HEAD"]);

    // Create _agentrack branch on remote
    git(work, ["branch", WORKTREE_BRANCH]);
    git(work, ["push", "-u", "origin", WORKTREE_BRANCH]);
    // Delete local branch so scenario is purely remote-based
    git(work, ["branch", "-D", WORKTREE_BRANCH]);

    const scenario = detectInitScenario(work);
    expect(scenario).toBe("join");
  });

  test("returns 'fresh' when no remote configured", () => {
    // No remote at all — should default to fresh
    const scenario = detectInitScenario(work);
    expect(scenario).toBe("fresh");
  });
});

// ─── isWorktreeInitialized ─────────────────────────────────────────────

describe("isWorktreeInitialized", () => {
  let base: string;
  let work: string;

  beforeEach(() => {
    base = createTestDir();
    work = join(base, "work");
    initGitRepo(work);
    makeInitialCommit(work);
  });

  afterEach(() => {
    cleanup(base);
  });

  test("returns false when no worktree exists", () => {
    expect(isWorktreeInitialized(work)).toBe(false);
  });

  test("returns true after worktree is mounted", () => {
    // Create branch and mount worktree
    git(work, ["branch", WORKTREE_BRANCH]);
    git(work, ["worktree", "add", WORKTREE_DIR, WORKTREE_BRANCH]);

    expect(isWorktreeInitialized(work)).toBe(true);
  });

  test("returns false when .agentrack/ is a regular directory (not a worktree)", () => {
    mkdirSync(join(work, WORKTREE_DIR));
    expect(isWorktreeInitialized(work)).toBe(false);
  });

  test("returns false in a non-git directory", () => {
    const nonGitDir = join(base, "non-git");
    mkdirSync(nonGitDir, { recursive: true });
    expect(isWorktreeInitialized(nonGitDir)).toBe(false);
  });
});

// ─── initFreshWorktree ─────────────────────────────────────────────────

describe("initFreshWorktree", () => {
  let base: string;
  let work: string;

  beforeEach(() => {
    base = createTestDir();
    work = join(base, "work");
    initGitRepo(work);
    makeInitialCommit(work);
  });

  afterEach(() => {
    cleanup(base);
  });

  test("creates orphan branch and mounts worktree (no remote)", () => {
    const result = initFreshWorktree(work);

    expect(result.scenario).toBe("fresh");
    expect(result.path).toBe(join(work, WORKTREE_DIR));
    expect(existsSync(join(work, WORKTREE_DIR))).toBe(true);

    // Verify branch exists
    const branches = git(work, ["branch", "--list", WORKTREE_BRANCH]);
    expect(branches.trim()).toContain(WORKTREE_BRANCH);
  });

  test("creates initial data files in the worktree", () => {
    initFreshWorktree(work);

    const wtDir = join(work, WORKTREE_DIR);
    expect(existsSync(join(wtDir, "config.json"))).toBe(true);
    expect(existsSync(join(wtDir, "index.json"))).toBe(true);
    expect(existsSync(join(wtDir, "dependencies.json"))).toBe(true);
    expect(existsSync(join(wtDir, "users.json"))).toBe(true);
  });

  test("data files contain correct default content", () => {
    initFreshWorktree(work);

    const wtDir = join(work, WORKTREE_DIR);
    const config = JSON.parse(readFileSync(join(wtDir, "config.json"), "utf-8"));
    expect(config).toEqual({ auth: { mode: "open", defaultUser: "anonymous" } });

    const index = JSON.parse(readFileSync(join(wtDir, "index.json"), "utf-8"));
    expect(index).toEqual({ open: [], closed: [], childrenOf: {} });

    const deps = JSON.parse(readFileSync(join(wtDir, "dependencies.json"), "utf-8"));
    expect(deps).toEqual({ blockedBy: {}, blocks: {} });

    const users = JSON.parse(readFileSync(join(wtDir, "users.json"), "utf-8"));
    expect(users).toEqual({ users: [] });
  });

  test("adds .gitignore entry for .agentrack/", () => {
    initFreshWorktree(work);

    const gitignorePath = join(work, ".gitignore");
    expect(existsSync(gitignorePath)).toBe(true);
    const content = readFileSync(gitignorePath, "utf-8");
    expect(content).toContain("/.agentrack/");
  });

  test("does not duplicate .gitignore entry if already present", () => {
    // Pre-create .gitignore with the entry
    writeFileSync(join(work, ".gitignore"), "/.agentrack/\n", "utf-8");

    initFreshWorktree(work);

    const content = readFileSync(join(work, ".gitignore"), "utf-8");
    const matches = content.match(/\.agentrack/g);
    expect(matches).toHaveLength(1);
  });

  test("with remote: pushes orphan branch to origin", () => {
    const remote = join(base, "remote.git");
    git(base, ["init", "--bare", remote]);
    git(work, ["remote", "add", "origin", remote]);
    git(work, ["push", "-u", "origin", "HEAD"]);

    initFreshWorktree(work);

    // Verify remote has the _agentrack branch
    const remoteBranches = git(work, ["branch", "-r"]);
    expect(remoteBranches).toContain(`origin/${WORKTREE_BRANCH}`);
  });
});

// ─── initJoinWorktree ──────────────────────────────────────────────────

describe("initJoinWorktree", () => {
  let base: string;

  beforeEach(() => {
    base = createTestDir();
  });

  afterEach(() => {
    cleanup(base);
  });

  test("fetches remote branch and mounts worktree", () => {
    const { remote, work } = setupRemoteAndClone();

    // First, create _agentrack on remote via another clone
    const other = join(base, "other");
    git(base, ["clone", remote, other]);
    git(other, ["config", "user.name", "Test User"]);
    git(other, ["config", "user.email", "test@example.com"]);

    // Create orphan-like branch and push
    const tree = git(other, ["write-tree"]);
    const commit = git(other, ["commit-tree", tree, "-m", "init _agentrack branch"]);
    git(other, ["branch", WORKTREE_BRANCH, commit.trim()]);
    git(other, ["push", "-u", "origin", WORKTREE_BRANCH]);

    // Now join from the main work clone
    const result = initJoinWorktree(work);

    expect(result.scenario).toBe("join");
    expect(result.path).toBe(join(work, WORKTREE_DIR));
    expect(existsSync(join(work, WORKTREE_DIR))).toBe(true);
    expect(isWorktreeInitialized(work)).toBe(true);
  });

  test("ensures .gitignore entry exists", () => {
    const { remote, work } = setupRemoteAndClone();

    // Push _agentrack branch to remote
    git(work, ["branch", WORKTREE_BRANCH]);
    git(work, ["push", "-u", "origin", WORKTREE_BRANCH]);
    // Remove local branch so join must recreate it
    git(work, ["branch", "-D", WORKTREE_BRANCH]);
    // Remove worktree if it was created
    try {
      git(work, ["worktree", "remove", WORKTREE_DIR, "--force"]);
    } catch {
      // ignore
    }

    initJoinWorktree(work);

    const gitignore = readFileSync(join(work, ".gitignore"), "utf-8");
    expect(gitignore).toContain("/.agentrack/");
  });
});

// ─── initWorktree (integration) ────────────────────────────────────────

describe("initWorktree", () => {
  let base: string;

  beforeEach(() => {
    base = createTestDir();
  });

  afterEach(() => {
    cleanup(base);
  });

  test("returns path when already initialized", () => {
    const work = join(base, "work");
    initGitRepo(work);
    makeInitialCommit(work);

    // Initialize once
    initWorktree(work);
    // Initialize again — should return without error
    const result = initWorktree(work);
    expect(result.path).toBe(join(work, WORKTREE_DIR));
    expect(isWorktreeInitialized(work)).toBe(true);
  });

  test("throws NOT_A_GIT_REPO when not inside a git repo", () => {
    const nonGitDir = join(base, "non-git");
    mkdirSync(nonGitDir, { recursive: true });

    try {
      initWorktree(nonGitDir);
      expect.unreachable("Should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(AgentrackError);
      expect((err as AgentrackError).result).toBe("NOT_A_GIT_REPO");
      expect((err as AgentrackError).message).toBe("Not inside a git repository");
      expect((err as AgentrackError).exitCode).toBe(13);
    }
  });

  test("throws MIGRATION_REQUIRED when .agentrack/ is a legacy directory", () => {
    const work = join(base, "work");
    initGitRepo(work);
    makeInitialCommit(work);

    // Create legacy .agentrack directory (not a worktree)
    mkdirSync(join(work, WORKTREE_DIR));

    try {
      initWorktree(work);
      expect.unreachable("Should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(AgentrackError);
      expect((err as AgentrackError).result).toBe("MIGRATION_REQUIRED");
      expect((err as AgentrackError).message).toContain("not a git worktree");
      expect((err as AgentrackError).exitCode).toBe(14);
    }
  });

  test("throws INVALID_STATE when currently on _agentrack branch", () => {
    const work = join(base, "work");
    initGitRepo(work);
    makeInitialCommit(work);

    // Create and checkout the _agentrack branch
    git(work, ["branch", WORKTREE_BRANCH]);
    git(work, ["checkout", WORKTREE_BRANCH]);

    try {
      initWorktree(work);
      expect.unreachable("Should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(AgentrackError);
      expect((err as AgentrackError).result).toBe("INVALID_STATE");
      expect((err as AgentrackError).message).toContain("currently on the _agentrack branch");
      expect((err as AgentrackError).exitCode).toBe(15);
    }
  });

  test("throws MIGRATION_REQUIRED when .agentrack/ is a file (not a directory)", () => {
    const work = join(base, "work");
    initGitRepo(work);
    makeInitialCommit(work);

    // Create .agentrack as a file (not a directory)
    writeFileSync(join(work, WORKTREE_DIR), "some content", "utf-8");

    try {
      initWorktree(work);
      expect.unreachable("Should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(AgentrackError);
      expect((err as AgentrackError).result).toBe("MIGRATION_REQUIRED");
      expect((err as AgentrackError).exitCode).toBe(14);
    }
  });

  test("fresh scenario: creates worktree in repo without remote _agentrack", () => {
    const { remote, work } = setupRemoteAndClone();
    // No _agentrack on remote yet
    const result = initWorktree(work);
    expect(result.scenario).toBe("fresh");
    expect(result.path).toBe(join(work, WORKTREE_DIR));
  });
});

// ─── pushWorktree ──────────────────────────────────────────────────────

describe("pushWorktree", () => {
  let base: string;

  beforeEach(() => {
    base = createTestDir();
  });

  afterEach(() => {
    cleanup(base);
  });

  test("throws NOT_INITIALIZED when worktree is not set up", () => {
    const work = join(base, "work");
    initGitRepo(work);
    makeInitialCommit(work);

    try {
      pushWorktree(work);
      expect.unreachable("Should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(AgentrackError);
      expect((err as AgentrackError).result).toBe("NOT_INITIALIZED");
      expect((err as AgentrackError).message).toBe("Agentrack not initialized. Run `agt init` first.");
      expect((err as AgentrackError).exitCode).toBe(1);
    }
  });

  test("returns synced: false when no changes to sync", () => {
    const { remote, work } = setupRemoteAndClone();
    initFreshWorktree(work);

    // Set up tracking for the worktree branch
    const wtDir = join(work, WORKTREE_DIR);
    try {
      git(wtDir, ["push", "-u", "origin", WORKTREE_BRANCH]);
    } catch {
      // might already be tracking
    }

    const result = pushWorktree(work);
    expect(result.synced).toBe(false);
    expect(result.message).toBe("No changes to sync");
  });

  test("returns synced: true with commitCount: 1 when changes exist", () => {
    const { remote, work } = setupRemoteAndClone();
    initFreshWorktree(work);

    const wtDir = join(work, WORKTREE_DIR);
    // Set up tracking
    try {
      git(wtDir, ["push", "-u", "origin", WORKTREE_BRANCH]);
    } catch {
      // might already be tracking
    }

    // Make a change inside the worktree
    writeFileSync(join(wtDir, "test-file.txt"), "hello", "utf-8");

    const result = pushWorktree(work);
    expect(result.synced).toBe(true);
    expect(result.commitCount).toBe(1);
  });

  test("uses custom commit message when provided", () => {
    const { remote, work } = setupRemoteAndClone();
    initFreshWorktree(work);

    const wtDir = join(work, WORKTREE_DIR);
    try {
      git(wtDir, ["push", "-u", "origin", WORKTREE_BRANCH]);
    } catch {
      // might already be tracking
    }

    writeFileSync(join(wtDir, "custom-msg.txt"), "hello", "utf-8");

    pushWorktree(work, "custom: my commit message");

    // Verify commit message on the branch
    const log = git(wtDir, ["log", "-1", "--format=%s"]);
    expect(log.trim()).toBe("custom: my commit message");
  });

  test("auto-generates sync: <timestamp> commit message", () => {
    const { remote, work } = setupRemoteAndClone();
    initFreshWorktree(work);

    const wtDir = join(work, WORKTREE_DIR);
    try {
      git(wtDir, ["push", "-u", "origin", WORKTREE_BRANCH]);
    } catch {
      // might already be tracking
    }

    writeFileSync(join(wtDir, "auto-msg.txt"), "hello", "utf-8");

    pushWorktree(work);

    const log = git(wtDir, ["log", "-1", "--format=%s"]);
    expect(log.trim()).toMatch(/^sync: \d{4}-\d{2}-\d{2}T/);
  });
});

// ─── pullWorktree ──────────────────────────────────────────────────────

describe("pullWorktree", () => {
  let base: string;

  beforeEach(() => {
    base = createTestDir();
  });

  afterEach(() => {
    cleanup(base);
  });

  test("throws NOT_INITIALIZED when worktree is not set up", () => {
    const work = join(base, "work");
    initGitRepo(work);
    makeInitialCommit(work);

    try {
      pullWorktree(work);
      expect.unreachable("Should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(AgentrackError);
      expect((err as AgentrackError).result).toBe("NOT_INITIALIZED");
      expect((err as AgentrackError).exitCode).toBe(1);
    }
  });

  test("returns updated: false when already up to date", () => {
    const { remote, work } = setupRemoteAndClone();
    initFreshWorktree(work);

    const wtDir = join(work, WORKTREE_DIR);
    try {
      git(wtDir, ["push", "-u", "origin", WORKTREE_BRANCH]);
    } catch {
      // might already be tracking
    }

    const result = pullWorktree(work);
    expect(result.updated).toBe(false);
  });

  test("returns updated: true when remote has new commits", () => {
    const { remote, work } = setupRemoteAndClone();
    initFreshWorktree(work);

    const wtDir = join(work, WORKTREE_DIR);
    try {
      git(wtDir, ["push", "-u", "origin", WORKTREE_BRANCH]);
    } catch {
      // might already be tracking
    }

    // Push a new commit from another clone
    const other = join(base, "other");
    git(base, ["clone", remote, other]);
    git(other, ["config", "user.name", "Test User"]);
    git(other, ["config", "user.email", "test@example.com"]);

    // Fetch _agentrack, make a change, push
    git(other, ["fetch", "origin", WORKTREE_BRANCH]);
    git(other, ["branch", WORKTREE_BRANCH, "origin/_agentrack"]);
    git(other, ["checkout", WORKTREE_BRANCH]);
    writeFileSync(join(other, "remote-change.txt"), "from other", "utf-8");
    git(other, ["add", "-A"]);
    git(other, ["commit", "-m", "remote change"]);
    git(other, ["push", "origin", WORKTREE_BRANCH]);

    // Now pull from the main work clone
    const result = pullWorktree(work);
    expect(result.updated).toBe(true);
  });

  test("throws PULL_FAILED when pull encounters an error", () => {
    const { remote, work } = setupRemoteAndClone();
    initFreshWorktree(work);

    const wtDir = join(work, WORKTREE_DIR);
    try {
      git(wtDir, ["push", "-u", "origin", WORKTREE_BRANCH]);
    } catch {
      // might already be tracking
    }

    // Remove remote to cause a failure
    rmSync(remote, { recursive: true, force: true });

