    pushWorktree(work, "custom: my commit message");

    const log = git(wtDir, ["log", "-1", "--format=%s"]);
    expect(log.trim()).toBe("custom: my commit message");
  });

  test("auto-generates sync: <timestamp> commit message", () => {
