    git(work, ["push", "-u", "origin", WORKTREE_BRANCH]);
    // Remove local branch so join must recreate it
    git(work, ["branch", "-D", WORKTREE_BRANCH]);
    // Remove worktree if it was created
    try {
      git(work, ["worktree", "remove", WORKTREE_DIR, "--force"]);
