import { AgentrackError } from "../../src/core/errors";

function createTestDir(prefix = "worktree-test"): string {
  const dir = join(tmpdir(), prefix + "-" + Date.now() + "-" + Math.random().toString(36).slice(2, 8));
  mkdirSync(dir, { recursive: true });
  return dir;
}

function git(cwd: string, args: string[]): string {
  return execFileSync("git", args, { cwd, encoding: "utf-8", stdio: ["pipe", "pipe", "pipe"] });
}

function initGitRepo(dir: string): void {
  git(dir, ["init"]);
  git(dir, ["config", "user.name", "Test User"]);
  git(dir, ["config", "user.email", "test@example.com"]);
}

function makeInitialCommit(dir: string): void {
  writeFileSync(join(dir, "README.md"), "# Test\n", "utf-8");
  git(dir, ["add", "README.md"]);
  git(dir, ["commit", "-m", "initial commit"]);
}

function setupRemoteAndClone(): { remote: string; work: string; base: string } {
  const base = createTestDir();
  const remote = join(base, "remote.git");
  const work = join(base, "work");
  git(base, ["init", "--bare", remote]);
  git(base, ["clone", remote, work]);
  git(work, ["config", "user.name", "Test User"]);
  git(work, ["config", "user.email", "test@example.com"]);
  makeInitialCommit(work);
  git(work, ["push", "-u", "origin", "HEAD"]);
  return { remote, work, base };
}

function cleanup(dir: string): void {
  try { git(dir, ["worktree", "prune"]); } catch { /* ignore */ }
  rmSync(dir, { recursive: true, force: true });
}

