    const content = readFileSync(join(work, ".gitignore"), "utf-8");
    const matches = content.match(/\.agentrack/g);
    expect(matches).toHaveLength(1);
  });

  test("recognizes /.agentrack without trailing slash", () => {
    writeFileSync(join(work, ".gitignore"), "/.agentrack\n", "utf-8");
    initFreshWorktree(work);
    const content = readFileSync(join(work, ".gitignore"), "utf-8");
    const matches = content.match(/\.agentrack/g);
    expect(matches).toHaveLength(1);
  });
});
